  'priv.deleteBody': 'This removes every booking, setting and record from this device and signs you out. It cannot be undone.',
  'priv.exportLink': 'Download my data first',
  'priv.deleteExplain': 'Download keeps a copy as a file on this device (your trips, notes, settings and what the server holds for you). Deleting removes your saved documents from the server; booking documents shared with other guests on your booking stay for them. Your audit trail is kept as a record of the deletion. Ask Guest Services if you want the account itself closed.',
