  'lit.title': 'Learn the ship in a minute',
  'lit.intro': 'A short guide to how decks, ends and lifts work, then the way from your cabin to the places most guests look for first. It is a teaching aid, not navigation: use the route finder and the deck plan for the real way.',
  'lit.rule1': 'The first digits of a cabin number are its deck. Cabin 12045 is on deck 12.',
  'lit.rule2': 'Forward is the bow (front), aft is the stern (back). Port is left and starboard is right when you face forward.',
  'lit.rule3': 'Lift banks A and B are forward, C and D midship, E and F aft. Your muster station letter is also a nearby lift bank.',
  'lit.rule4': 'Higher deck numbers are higher up. Public rooms are mostly on decks 6 to 9, with the pools and the Lido on deck 17.',
