  'away.item.contact': 'Leave your itinerary and a contact with someone at home.',
  'away.why.contact': 'Share the ship’s emergency number, not your cabin number.',
  'away.item.mail': 'Mail and parcels held or collected by someone.',
  'away.why.mail': 'Stop deliveries or ask a neighbour.',
  'away.item.keys': 'A spare key with someone you trust.',
  'away.why.keys': 'Tell them who else may come in.',
  'away.item.lights': 'Lights on timers or a neighbour told you are away.',
  'away.why.lights': 'A lived-in look is the easiest deterrent.',
  'away.item.bins': 'Bins out, and a plan for the next collection day.',
  'away.why.bins': 'Empty the kitchen bin on the last day.',
  'away.item.fridge': 'Fridge cleared of anything that will not keep.',
  'away.why.fridge': 'Check the dates on milk and fresh food.',
  'away.item.safety': 'Home safety check: stove and heaters off, windows and doors locked, water shut off if you wish.',
  'away.why.safety': 'Do it the day you leave, last thing.',
  'away.item.bills': 'Bills due while you are away paid or set to pay by themselves.',
  'away.why.bills': 'Check card payments that fall in the week you sail.',
  'away.item.bank': 'Banks told you are travelling, and a back-up card kept apart from your wallet.',
  'away.why.bank': 'Put a note on the card app if it asks.',
  'away.item.ooo': 'Out-of-office reply written, with a name for urgent things.',
  'away.why.ooo': 'Set it to start the day you sail.',
  'away.item.handover': 'Work handed over, with passwords and files someone else needs.',
  'away.why.handover': 'Do not leave passwords in an email.',
  'away.item.supply': 'Enough regular medicine for the trip plus a few spare days, in the original containers.',
  'away.why.supply': 'Ask the pharmacy at least two weeks before.',
