  'screen.X07.title': 'Stage Overview',
  'screen.X07.subtext': 'A welcome to your stage of the journey: where you have come from, what this stage is for and the steps to take.',
  'welcome.eyebrow': 'Welcome to your next stage',
  'stanleyIntro.eyebrow': 'Welcome aboard',
  'stanleyIntro.title': 'Hello, I am Stanley',
  'stanleyIntro.h.who': 'Your travel companion',
  'stanleyIntro.who': 'I am Stanley, your guide for the whole trip: from dreaming and booking, through getting to the ship and life on board, to remembering it all afterwards. I am always just a tap away.',
  'stanleyIntro.h.can': 'What I can do',
  'stanleyIntro.can.1': 'Answer your questions about your cruise, your ship, the ports and your bill, in plain words.',
  'stanleyIntro.can.2': 'Do things for you, with your OK: book a dinner, add an excursion, change your day, set a reminder. I always show you first, and most things can be undone.',
  'stanleyIntro.can.3': 'Keep watch: tell you when something changes and what it means for you, and remind you before a deadline.',
  'stanleyIntro.can.4': 'Help you get more from your trip: find what you have already paid for and suggest things you will enjoy.',
  'stanleyIntro.card.1': 'I answer',
  'stanleyIntro.card.2': 'I do things for you, with your OK',
  'stanleyIntro.card.3': 'I keep watch so you do not have to',
  'stanleyIntro.card.4': 'I help you get more from your trip',
  'stanleyIntro.try': 'Try it',
  'stanleyIntro.tryFor': 'Try it: {example}',
  'stanleyIntro.never.title': 'What I will never do',
  'stanleyIntro.never.body': 'Pay for anything, cancel or change your booking without your yes, share your details, message other people for you, or replace the ship\'s announcements. I am not a crew member. For anything urgent, ask a person.',
  'stanleyIntro.control.body': 'You decide how much I say. I never do anything without showing you first.',
  'stanleyAuthority.title': 'How much may I do?',
