  'stanleyAuto.title': 'My deadline reminders',
  'stanleyAuto.intro': 'If you have let me set your reminders, I add one for the day online check-in opens and two before your final payment is due, and one for the afternoon before the ship gets in, when the bags go out, and one an hour before your cabin has to be empty on the last morning, and one two weeks before sailing if a document is not ready, and one five days before sailing, three days before the dining plan freezes, and one an hour before all aboard on each port day, and one the evening before sailing to open your boarding pass. Each is on your reminders list and can be removed. I set nothing else and never pay or book anything.',
