  'stanleyGuardian.title': 'Children\'s all-aboard times',
  'stanleyGuardian.intro': 'If children are on your account, I can set a reminder on your own list an hour before all aboard on each port day, with the child\'s first name on it. The child gets nothing, and nobody else is told. You can remove any of them from your reminders.',
