  'stanleyAutoBook.title': 'My dinners, timings and usual requests',
  'stanleyAutoBook.intro': 'If you have let me, I book your usual main-dining table on nights with no dinner, keep a dinner at the time of your Keep my dinner rule when the programme changes, and send the one free stateroom request you always make. Each one is on your list of what I did, with time to undo it: two hours for a table, and until the crew is on the way for a request. I never book anything that costs money, never touch anyone else\'s booking and never pay.',
  'stanleyAutoBook.usual': 'My usual main-dining time',
