  'stanleyFamily.title': 'For the family',
  'stanleyFamily.intro': 'When there are children on the booking I point to the kids club and to muster for everyone. I never register a child, message a teen or mark anything done.',
  'stanleyFamily.loading': 'Looking at your trip.',
  'stanleyFamily.error': 'I could not look at that just now.',
