  'stanleyPlanningPack.clear': 'Nothing to add right now.',
  'stanleyPlanningPack.open': 'Open',
  'stanleyChecklist.title': 'What is left to do',
  'stanleyChecklist.intro': 'I list what is still open for each traveller, in the order that helps. Each item opens the screen where you do it, and it ticks off by itself when it is done. I never fill anything in for you.',
