  'stanleyBrief.title': 'Morning brief and evening look-ahead',
  'stanleyBrief.intro': 'Choose a time and I will send you today at a glance in the morning, or tomorrow in the evening. Nothing is sent until you turn one on, and never inside your quiet hours.',
