  'settings.welcome.title': 'Stage welcomes',
  'settings.welcome.intro': 'When you move to a new stage of your trip, a welcome page tells you what it is about, shown once. Reset to see the welcome for your stage again, and for each stage after it.',
  'settings.welcome.reset': 'Reset Stage Welcomes',
  'settings.welcome.done': 'Stage welcomes reset. You will see the welcome again the next time you open a page.',
